using Avalonia;
using Avalonia.Controls;
using Avalonia.Controls.ApplicationLifetimes;
using Avalonia.Media;
using Avalonia.Themes.Fluent;
using Avalonia.Threading;
using System.Text.Json;
namespace WirePulse;

public sealed class App : Application
{
    Settings settings = null!; Spectrum spectrum = new(); MediaService media = null!; AudioCapture audio = null!; SettingsWindow? panel; readonly List<(Window Window, WallpaperView View)> walls = []; DispatcherTimer timer = null!; TrayIcon? tray; bool polling; DateTime lastPoll = DateTime.MinValue; int ticks; bool quitting; readonly Dictionary<Window, DateTime> drawn = []; bool subscribed; bool lastIndependent; readonly Dictionary<string, Settings> profiles = []; readonly Dictionary<string, Settings> available = [];
    public override void Initialize() { Styles.Add(new FluentTheme()); RequestedThemeVariant = Avalonia.Styling.ThemeVariant.Dark; }
    public override void OnFrameworkInitializationCompleted()
    {
        if (ApplicationLifetime is IClassicDesktopStyleApplicationLifetime life)
        {
            life.ShutdownMode = ShutdownMode.OnExplicitShutdown; settings = new(); media = new(settings); audio = new(spectrum); audio.Start(); life.Exit += (_, _) => { quitting = true; audio.Dispose(); tray?.Dispose(); };
            var menu = new NativeMenu(); var show = new NativeMenuItem("Ajustes de WirePulse"); show.Click += (_, _) => ShowSettings(); menu.Add(show); var pause = new NativeMenuItem("Pausar / reanudar animación"); pause.Click += (_, _) => { settings.Paused = !settings.Paused; foreach (var p in profiles.Values) p.Paused = settings.Paused; }; menu.Add(pause); var exit = new NativeMenuItem("Salir"); exit.Click += (_, _) => life.Shutdown(); menu.Add(exit); tray = new TrayIcon { Icon = new WindowIcon(Path.Combine(AppContext.BaseDirectory, "Assets", "WirePulse.png")), ToolTipText = "WirePulse", Menu = menu, IsVisible = true }; tray.Clicked += (_, _) => ShowSettings(); TrayIcon.SetIcons(this, new TrayIcons { tray });
            lastIndependent = settings.IndependentDisplays; if(lastIndependent){foreach(var key in profiles.Keys.ToArray()){if(!profiles[key].HasSaved)profiles[key]=new Settings(key,settings);profiles[key].Save();}}CreateWalls(); if (!Program.Args.Contains("--no-settings")) ShowSettings(); timer = new DispatcherTimer(TimeSpan.FromMilliseconds(1000 / 120d), DispatcherPriority.Render, Tick); timer.Start(); settings.Changed += () => { if (lastIndependent != settings.IndependentDisplays) { lastIndependent = settings.IndependentDisplays; if(lastIndependent){foreach(var key in profiles.Keys.ToArray()){if(!profiles[key].HasSaved)profiles[key]=new Settings(key,settings);profiles[key].Save();}}CreateWalls(); } };
            if (double.TryParse(Program.Option("--probe-seconds"), out var seconds)) { var stop = new DispatcherTimer { Interval = TimeSpan.FromSeconds(seconds) }; stop.Tick += (_, _) => { WriteStatus(); if (Program.Option("--render-output") is string output && walls.Count > 0) { var view = walls[0].View; using var bitmap = new Avalonia.Media.Imaging.RenderTargetBitmap(new PixelSize((int)view.Bounds.Width, (int)view.Bounds.Height)); bitmap.Render(view); bitmap.Save(output); } life.Shutdown(); }; stop.Start(); }
        }
        base.OnFrameworkInitializationCompleted();
    }
    void ShowSettings() { if (panel == null) { panel = new SettingsWindow(settings, spectrum, media, () => audio.Status, available); panel.Closed += (_, _) => panel = null; } panel.Show(); panel.Activate(); }
    void CreateWalls() { foreach (var old in walls) old.Window.Close(); walls.Clear(); drawn.Clear(); var reference = panel ?? new Window(); var screens = reference.Screens.All; available.Clear(); int displayIndex = 0; foreach (var screen in screens) { string key = screen.DisplayName ?? ("Pantalla " + (++displayIndex)); if (available.ContainsKey(key)) key += " " + (++displayIndex); if (!profiles.TryGetValue(key, out var profile)) { profile = new Settings(key, settings); profiles[key] = profile; } available[key] = profile; var view = new WallpaperView(settings.IndependentDisplays ? profile : settings, spectrum, media); var window = new Window { Title = "WirePulse Desktop", SystemDecorations = SystemDecorations.None, ShowInTaskbar = false, CanResize = false, WindowStartupLocation = WindowStartupLocation.Manual, Position = screen.Bounds.Position, Width = screen.Bounds.Width / screen.Scaling, Height = screen.Bounds.Height / screen.Scaling, Background = Brushes.Black, Content = view, ShowActivated = false }; window.Opened += (_, _) => { try { var handle = window.TryGetPlatformHandle() ?? throw new Exception("No existe una ventana nativa"); DesktopHost.Attach(handle.Handle, screen.Bounds.Width, screen.Bounds.Height, screen.Bounds.X, screen.Bounds.Y); } catch (Exception e) { Console.Error.WriteLine(e); (ApplicationLifetime as IClassicDesktopStyleApplicationLifetime)?.Shutdown(1); } }; walls.Add((window, view)); window.Show(); } panel?.RefreshDisplays(); if (!subscribed) { subscribed = true; reference.Screens.Changed += (_, _) => { if (!quitting) Dispatcher.UIThread.Post(CreateWalls); }; } }
    async void Tick(object? sender, EventArgs e) { foreach (var w in walls) { var config = w.View.Configuration; double fps = config.On("unlimitedfps") ? 120 : Math.Clamp(config.N("fps"), 15, 120); if (!drawn.TryGetValue(w.Window, out var when) || (DateTime.UtcNow - when).TotalSeconds >= 1 / fps - .001) { w.View.InvalidateVisual(); drawn[w.Window] = DateTime.UtcNow; } } if (++ticks % 60 == 0) WriteStatus(); if (ticks % 240 == 0 && OperatingSystem.IsWindows() && walls.Any(w => !DesktopHost.Alive(w.Window.TryGetPlatformHandle()?.Handle ?? IntPtr.Zero))) Dispatcher.UIThread.Post(CreateWalls); if (!polling && (DateTime.UtcNow - lastPoll).TotalSeconds > 1) { polling = true; try { await media.Poll(); } finally { polling = false; lastPoll = DateTime.UtcNow; } } }
    void WriteStatus() { try { var s = spectrum.Snapshot(); var path = Program.Option("--probe-output") ?? Path.Combine(Settings.Folder, "status.json"); Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!); File.WriteAllText(path, JsonSerializer.Serialize(new { audio = audio.Status, rate = s.SampleRate, fft = s.FftSize, peak = s.PeakHz, frames = s.Frames, age = s.Age, bands = s.Bands, renderFrames = walls.Sum(w => w.View.Frames), provider = media.Current.Provider, title = media.Current.Title, media = media.Status }, new JsonSerializerOptions { WriteIndented = true })); } catch { } }
}
